import { useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowDown, ArrowLeft, ArrowRight, Bell, BellRing, CalendarDays, Check, CheckCheck, ChevronLeft, ChevronRight, Circle, Clock3, Folder, FolderOpen, LayoutDashboard, ListTodo, LogOut, Menu, MoreHorizontal, Pencil, Plus, Search, Sparkles, Trash2, X, Archive, RotateCcw, AlertTriangle, Play, Eye, EyeOff, Leaf, Settings2 } from 'lucide-react';
import { COLORS, DATA_PREFIX, STATUS_LABEL, PRIORITY_LABEL, uid, today, shiftDate, inputTime, toISO, datePart, dateLabel, timeLabel, overdue, progress, updateReminder, makeNotice, seedData, emptyData, loadData, type DemoUser, type Project, type Task, type Data, type Page, type Status } from './model';

const SESSION = 'projectrecord.demo.session';
const ACCOUNTS = 'projectrecord.demo.accounts';
let openModalCount = 0;
let previousBodyOverflow = '';
const DEMO_USER: DemoUser = { id: 'demo-user', name: 'พุฒิ ศรีสุข', email: 'demo@projectrecord.local' };
const PAGE_NAMES: Record<Page, string> = { dashboard: 'ภาพรวม', calendar: 'ปฏิทิน', tasks: 'To-do list', projects: 'โปรเจ็คของฉัน', create: 'สร้างโปรเจ็ค', detail: 'รายละเอียดโปรเจ็ค', notifications: 'การแจ้งเตือน' };
const NAV = [{ id: 'dashboard', label: 'ภาพรวม', icon: LayoutDashboard }, { id: 'calendar', label: 'ปฏิทิน', icon: CalendarDays }, { id: 'tasks', label: 'To-do list', icon: ListTodo }, { id: 'projects', label: 'โปรเจ็คของฉัน', icon: FolderOpen }] as const;
function readUser(): DemoUser | null { try { const u = JSON.parse(localStorage.getItem(SESSION) || 'null'); return u && typeof u.id === 'string' && typeof u.name === 'string' && typeof u.email === 'string' ? u : null; } catch { return null; } }
function readAccounts(): DemoUser[] { try { const users = JSON.parse(localStorage.getItem(ACCOUNTS) || '[]'); return Array.isArray(users) ? users.filter(u => typeof u.id === 'string' && typeof u.email === 'string' && typeof u.name === 'string') : []; } catch { return []; } }
function route(): Page { const name = location.hash.slice(1); return name in PAGE_NAMES ? name as Page : 'dashboard'; }
function Brand({ light = false }: { light?: boolean }) { return <div className={`brand ${light ? 'light' : ''}`}><span className="brand-icon"><Folder size={20} strokeWidth={2.5} /></span><span>Project<span className="brand-record">Record</span><small>MAKE ROOM FOR WHAT MATTERS</small></span></div>; }
function Badge({ children, kind = '' }: { children: ReactNode; kind?: string }) { return <span className={`badge ${kind}`}>{children}</span>; }
function Modal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { ref.current?.showModal(); if (openModalCount === 0) previousBodyOverflow = document.body.style.overflow; openModalCount++; document.body.style.overflow = 'hidden'; return () => { openModalCount--; if (openModalCount === 0) document.body.style.overflow = previousBodyOverflow; }; }, []);
  return <dialog ref={ref} className={`modal ${wide ? 'wide' : ''}`} aria-label={title} onCancel={e => { e.preventDefault(); onClose(); }} onClick={e => { if (e.target === ref.current) onClose(); }}><div className="modal-header"><h2>{title}</h2><button className="icon-btn" aria-label="ปิด" onClick={onClose}><X size={20} /></button></div>{children}</dialog>;
}

function Landing({ onAuth, onDemo }: { onAuth: (type: 'login' | 'register') => void; onDemo: () => void }) {
  return <div className="landing"><nav className="landing-nav"><Brand /><div className="landing-links"><a href="#features">สิ่งที่เราช่วยคุณได้</a><button className="btn ghost" onClick={() => onAuth('login')}>เข้าสู่ระบบ</button><button className="btn primary" onClick={() => onAuth('register')}>เริ่มใช้งาน <ArrowUpRight /></button></div></nav>
    <main className="landing-main"><div className="hero-copy"><div className="eyebrow"><span className="tiny-dot" /> A LITTLE PLAN. A LOT OF POSSIBILITIES.</div><h1>ทุกโปรเจ็คมีที่อยู่<br />ทุกวันมี<span className="serif-accent">แผนที่ดี</span></h1><p>เปลี่ยนงานที่กระจัดกระจายให้เป็นแผนที่ชัดเจน<br className="desktop-only" /> รวมโปรเจ็ค To-do list ปฏิทิน และการแจ้งเตือน<br className="desktop-only" /> ไว้ในพื้นที่เดียวที่คุณจัดการได้</p><div className="hero-actions"><button className="btn primary big" onClick={onDemo}>ลองใช้งานเดโม <ArrowRight size={18} /></button><button className="btn outline big" onClick={() => onAuth('register')}>สร้างบัญชีจำลอง</button></div><div className="hero-note"><Check size={15} /> ไม่ต้องใช้ API key <span>·</span> ข้อมูลอยู่ในเบราว์เซอร์ของคุณ</div><div className="hero-proof"><div className="mini-avatars"><span>พ</span><span>น</span><span>ศ</span></div><div><strong>สำหรับวันเรียนและวันทำโปรเจ็ค</strong><small>เริ่มจากงานเล็ก ๆ แล้วค่อยไปให้ถึงเป้าหมาย</small></div></div></div>
    <div className="hero-art"><div className="orbit orbit-one" /><div className="orbit orbit-two" /><div className="floating-note"><span className="note-icon"><CheckCheck size={22} /></span><div><strong>ทีละงาน ทีละก้าว</strong><small>วันนี้ก็เดินหน้าได้อีกหน่อย</small></div><Sparkles size={18} /></div><div className="preview-board"><div className="preview-top"><div><span className="eyebrow">YOUR WEEK, AT A GLANCE</span><h3>พื้นที่สำหรับแผนของคุณ</h3></div><span className="preview-avatar">พ</span></div><div className="preview-week">{['จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส', 'อา'].map((v, i) => <div key={i} className={i === 2 ? 'chosen' : ''}><span>{v}</span><strong>{i + 5}</strong></div>)}</div><div className="preview-section"><span>แผนวันนี้</span><MoreHorizontal size={19} /></div><div className="preview-task"><span className="check-circle checked"><Check size={14} /></span><div><strong>วางโครงสร้างโปรเจ็ค</strong><small>ProjectRecord · เสร็จเรียบร้อย</small></div></div><div className="preview-task active"><span className="check-circle"><Circle size={13} /></span><div><strong>ออกแบบหน้าปฏิทิน</strong><small><Clock3 size={12} /> 13:00 – 15:00</small></div><span className="preview-pill">กำลังทำ</span></div><div className="preview-task"><span className="check-circle" /><div><strong>เตรียมสไลด์นำเสนอ</strong><small>ProjectRecord · งานถัดไป</small></div></div><div className="preview-progress"><div><span>ความคืบหน้าของโปรเจ็ค</span><strong>33%</strong></div><div className="progress-track"><span style={{ width: '33%' }} /></div></div></div><div className="floating-reminder"><span><BellRing size={20} /></span><div><strong>ใกล้ถึงเวลาเริ่มงานแล้ว</strong><small>ออกแบบหน้าปฏิทิน · อีก 10 นาที</small></div></div><div className="art-caption"><Leaf size={17} /> CLEAR YOUR MIND. FIND YOUR FLOW.</div></div></main>
    <section className="landing-features" id="features"><div><span className="eyebrow">LESS SCATTER. MORE CLARITY.</span><h2>จากไอเดีย สู่วันที่ทำได้จริง</h2></div><article><FolderOpen /><h3>แบ่งโปรเจ็คให้เริ่มได้</h3><p>เปลี่ยนเป้าหมายใหญ่เป็นงานย่อย พร้อมกำหนดส่งที่ชัดเจน</p></article><article><CalendarDays /><h3>เห็นเวลาเป็นภาพเดียว</h3><p>จัดช่วงเวลาทำงานและดูทุกโปรเจ็คบนปฏิทินเดียวกัน</p></article><article><Bell /><h3>มีตัวช่วยเตือนให้จำ</h3><p>เตือนก่อนเริ่มงานหรือก่อนกำหนดส่ง แล้วติดตามสิ่งที่ทำสำเร็จ</p></article></section><footer className="landing-footer"><span>© {new Date().getFullYear()} ProjectRecord</span><span>สร้างพื้นที่ให้ทุกแผนของคุณ · Demo edition</span></footer></div>;
}
function ArrowUpRight() { return <ArrowRight size={16} className="up-arrow" />; }

function Auth({ type, onType, onBack, onUser, onDemo }: { type: 'login' | 'register'; onType: (t: 'login' | 'register') => void; onBack: () => void; onUser: (u: DemoUser) => void; onDemo: () => void }) {
  const [error, setError] = useState(''); const [show, setShow] = useState(false); const [busy, setBusy] = useState(false);
  function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setError(''); const form = new FormData(e.currentTarget); const email = String(form.get('email')).trim().toLowerCase(); const password = String(form.get('password')); const name = String(form.get('name') || '').trim();
    if (password.length < 6) { setError('กรุณาใช้รหัสผ่านจำลองอย่างน้อย 6 ตัวอักษร'); return; }
    try {
      const accounts = readAccounts(); let user: DemoUser | undefined;
      if (type === 'register') {
        if (!name) { setError('กรุณากรอกชื่อของคุณ'); return; }
        if (password !== String(form.get('confirm'))) { setError('รหัสผ่านทั้งสองช่องไม่ตรงกัน'); return; }
        if (accounts.some(a => a.email === email) || email === DEMO_USER.email) { setError('อีเมลนี้มีบัญชีจำลองแล้ว กรุณาเข้าสู่ระบบ'); return; }
        user = { id: uid(), name, email }; localStorage.setItem(ACCOUNTS, JSON.stringify([...accounts, user]));
      } else {
        user = email === DEMO_USER.email ? DEMO_USER : accounts.find(a => a.email === email);
        if (!user) { setError('ไม่พบบัญชีจำลองนี้ กรุณาสมัครสมาชิกก่อน หรือเลือกลองใช้เดโม'); return; }
      }
      setBusy(true); onUser(user);
    } catch { setError('บันทึกบัญชีไม่ได้ กรุณาเปิดใช้งานพื้นที่จัดเก็บของเบราว์เซอร์'); setBusy(false); }
  }
  return <div className="auth-page"><aside className="auth-aside"><Brand light /><div><span className="eyebrow">A FRESH START, EVERY DAY.</span><h1>แผนที่ดี<br />เริ่มต้นจาก<br /><span>พื้นที่ของคุณ</span></h1><p>โปรเจ็ค งานย่อย และเวลาที่คุณตั้งใจ<br />ทุกอย่างอยู่ด้วยกันที่นี่</p><div className="auth-quote"><Leaf size={24} /><p>“ไม่ต้องทำทุกอย่างในวันเดียว<br />แค่รู้ว่าวันนี้จะเริ่มจากอะไร”</p></div></div><small>ProjectRecord · Demo edition</small></aside><main className="auth-main"><button className="back-link" onClick={onBack}><ArrowLeft size={16} /> กลับหน้าหลัก</button><div className="auth-form-wrap"><span className="eyebrow">YOUR OWN LITTLE WORKSPACE</span><h2>{type === 'login' ? 'ยินดีต้อนรับกลับมา' : 'เริ่มต้นแผนใหม่ด้วยกัน'}</h2><p>{type === 'login' ? 'เข้าสู่พื้นที่ทำงาน แล้วไปต่อจากสิ่งที่คุณวางไว้' : 'สร้างบัญชีจำลองสำหรับเก็บโปรเจ็คของคุณบนเครื่องนี้'}</p><form onSubmit={submit} key={type}>{type === 'register' && <label>ชื่อของคุณ<input name="name" autoComplete="name" placeholder="เช่น พุฒิ ศรีสุข" required maxLength={80} /></label>}<label>อีเมล<input name="email" type="email" autoComplete="email" placeholder="you@example.com" required /></label><label>รหัสผ่านจำลอง<div className="password-wrap"><input name="password" type={show ? 'text' : 'password'} autoComplete="off" placeholder="อย่างน้อย 6 ตัวอักษร" minLength={6} required /><button className="icon-btn" type="button" aria-label={show ? 'ซ่อนรหัสผ่าน' : 'แสดงรหัสผ่าน'} onClick={() => setShow(!show)}>{show ? <EyeOff size={18} /> : <Eye size={18} />}</button></div></label>{type === 'register' && <label>ยืนยันรหัสผ่านจำลอง<input name="confirm" type={show ? 'text' : 'password'} autoComplete="off" minLength={6} required placeholder="กรอกรหัสผ่านอีกครั้ง" /></label>}{error && <div className="form-error" role="alert">{error}</div>}<div className="demo-disclosure"><Sparkles size={17} /><span>บัญชีนี้เป็นการจำลอง ไม่เก็บรหัสผ่าน และยอมรับรหัสผ่านใดก็ได้ที่ยาว 6 ตัวอักษรขึ้นไปเมื่อเข้าสู่ระบบ โปรดใช้ข้อมูลสมมติ</span></div><button className="btn primary full" disabled={busy}>{type === 'login' ? 'เข้าสู่ระบบ' : 'สร้างบัญชีจำลอง'} <ArrowRight size={17} /></button></form><div className="auth-switch">{type === 'login' ? 'ยังไม่มีบัญชี?' : 'มีบัญชีอยู่แล้ว?'} <button onClick={() => { setError(''); onType(type === 'login' ? 'register' : 'login'); }}>{type === 'login' ? 'สมัครสมาชิก' : 'เข้าสู่ระบบ'}</button></div><div className="divider"><span>หรือเริ่มสำรวจได้เลย</span></div><button className="btn outline full" onClick={onDemo}><Play size={16} /> ลองใช้เดโมพร้อมข้อมูลตัวอย่าง</button></div><small className="auth-foot">ข้อมูลจะอยู่เฉพาะเบราว์เซอร์และเครื่องที่ใช้งาน</small></main></div>;
}

function TaskRow({ task, project, onStatus, onEdit, compact = false }: { task: Task; project?: Project; onStatus: (t: Task, s: Status) => void; onEdit: (t: Task) => void; compact?: boolean }) {
  return <div className={`task-row ${task.status === 'done' ? 'completed' : ''}`}><button className={`task-check ${task.status === 'done' ? 'checked' : ''}`} onClick={() => onStatus(task, task.status === 'done' ? 'todo' : 'done')} aria-label={`${task.status === 'done' ? 'ยกเลิกสถานะเสร็จ' : 'ทำเครื่องหมายเสร็จ'}: ${task.title}`}>{task.status === 'done' && <Check size={16} />}</button><button className="task-copy" onClick={() => onEdit(task)}><strong>{task.title}</strong><span><i style={{ background: project?.color }} />{project?.name || 'โปรเจ็ค'}{task.start && <><span className="meta-separator">·</span><Clock3 size={12} />{dateLabel(task.start)} {timeLabel(task.start)}{task.end && `–${timeLabel(task.end)}`}</>}</span></button>{!compact && <span className={`priority-text ${task.priority}`}><span />{PRIORITY_LABEL[task.priority]}</span>}<div className="task-deadline">{task.due && <span className={overdue(task) ? 'overdue-text' : ''}>{dateLabel(task.due)} <span className="desktop-only">{timeLabel(task.due)}</span></span>}<Badge kind={overdue(task) ? 'late' : task.status}>{overdue(task) ? 'เลยกำหนด' : STATUS_LABEL[task.status]}</Badge></div><button className="icon-btn row-edit" aria-label={`แก้ไข ${task.title}`} onClick={() => onEdit(task)}><Pencil size={15} /></button></div>;
}
function Empty({ title, description, action }: { title: string; description: string; action?: ReactNode }) { return <div className="empty-state"><span><Leaf size={28} /></span><h3>{title}</h3><p>{description}</p>{action}</div>; }
function ProjectCard({ project, tasks, onOpen }: { project: Project; tasks: Task[]; onOpen: () => void }) { const completed = tasks.filter(t => t.status === 'done').length; return <button className="project-card" onClick={onOpen}><div className="project-card-top"><span className="folder-tile" style={{ color: project.color, background: `${project.color}15` }}><Folder size={21} /></span><Badge kind={project.archived ? 'neutral' : tasks.length && completed === tasks.length ? 'done' : 'doing'}>{project.archived ? 'เก็บเข้าคลัง' : tasks.length && completed === tasks.length ? 'เสร็จแล้ว' : 'กำลังดำเนินการ'}</Badge></div><h3>{project.name}</h3><p>{project.description || 'ยังไม่มีรายละเอียดโปรเจ็ค'}</p><div className="project-progress-label"><span>{tasks.length ? `${completed}/${tasks.length} งานสำเร็จ` : 'ยังไม่มีงาน'}</span><strong>{tasks.length ? `${progress(tasks)}%` : '—'}</strong></div><div className="progress-track"><span style={{ width: `${progress(tasks)}%`, background: project.color }} /></div><div className="project-card-footer"><span><CalendarDays size={14} /> ส่ง {dateLabel(project.due)}</span><ArrowRight size={17} /></div></button>; }

function Dashboard({ data, user, go, onOpen, onEdit, onStatus }: { data: Data; user: DemoUser; go: (p: Page) => void; onOpen: (p: Project) => void; onEdit: (t: Task) => void; onStatus: (t: Task, s: Status) => void }) {
  const active = data.projects.filter(p => !p.archived); const tasks = data.tasks.filter(t => active.some(p => p.id === t.projectId)); const day = today(); const todays = tasks.filter(t => (datePart(t.start) === day || datePart(t.due) === day) && t.status !== 'done'); const late = tasks.filter(overdue); const upcoming = tasks.filter(t => t.status !== 'done' && !!t.due && !overdue(t)).sort((a, b) => a.due.localeCompare(b.due)).slice(0, 4);
  return <><div className="page-heading"><div><span className="eyebrow">LET’S MAKE TODAY COUNT</span><h1>สวัสดี, {user.name.split(' ')[0]} <span className="greeting-sun">☀</span></h1><p>วันนี้มีอะไรให้เดินหน้าบ้าง? เริ่มจากแผนเล็ก ๆ ของคุณ</p></div><button className="btn primary" onClick={() => go('create')}><Plus size={17} /> สร้างโปรเจ็ค</button></div><div className="daily-banner"><div><span className="banner-leaf"><Leaf size={25} /></span><div><strong>{todays.length ? `วันนี้มี ${todays.length} งานรอคุณอยู่` : 'วันนี้มีพื้นที่ให้แผนใหม่ ๆ'}</strong><p>{late.length ? `มี ${late.length} งานเลยกำหนด ลองจัดเวลาให้ใหม่แล้วค่อยไปต่อ` : 'จัดเวลาให้สิ่งสำคัญ แล้วเดินหน้าในจังหวะของคุณ'}</p></div></div><button onClick={() => go('calendar')}>ดูแผนบนปฏิทิน <ArrowRight size={17} /></button></div><div className="stats-grid"><Stat label="โปรเจ็คที่กำลังทำ" value={active.length} icon={<FolderOpen />} note="ทุกแผนในพื้นที่ของคุณ" /><Stat label="งานที่ต้องทำวันนี้" value={todays.length} icon={<ListTodo />} note="เริ่มจากงานที่สำคัญก่อน" /><Stat label="งานที่เสร็จแล้ว" value={tasks.filter(t => t.status === 'done').length} icon={<CheckCheck />} note={`${tasks.length} งานทั้งหมด · ${progress(tasks)}% สำเร็จ`} /><Stat label="งานเลยกำหนด" value={late.length} icon={<Clock3 />} note={late.length ? 'ปรับแผนแล้วเริ่มใหม่ได้เสมอ' : 'ทุกอย่างยังอยู่ในแผน'} warning={late.length > 0} /></div><div className="dashboard-grid"><section className="panel"><div className="section-heading"><div><h2>แผนวันนี้ <span className="count-chip">{todays.length}</span></h2><p>{dateLabel(day, true)}</p></div><button className="text-btn" onClick={() => go('tasks')}>ดูงานทั้งหมด <ArrowRight size={15} /></button></div>{todays.length ? todays.map(t => <TaskRow key={t.id} task={t} project={active.find(p => p.id === t.projectId)} onEdit={onEdit} onStatus={onStatus} compact />) : <Empty title="วันนี้ยังไม่มีงานค้าง" description="ดูแผนวันถัดไป หรือเพิ่มงานใหม่ให้โปรเจ็คของคุณ" action={<button className="btn outline" onClick={() => go('calendar')}>เปิดปฏิทิน</button>} />}</section><section className="panel upcoming-panel"><div className="section-heading"><div><h2>ใกล้ถึงกำหนด</h2><p>สิ่งที่ควรเผื่อเวลาไว้</p></div><CalendarDays size={20} /></div>{upcoming.length ? upcoming.map(t => <button className="upcoming-item" key={t.id} onClick={() => onEdit(t)}><span className="date-tile"><strong>{Number(datePart(t.due).slice(8))}</strong><small>{dateLabel(t.due).split(' ').slice(1).join(' ')}</small></span><span><strong>{t.title}</strong><small>{active.find(p => p.id === t.projectId)?.name}</small></span><ChevronRight size={16} /></button>) : <Empty title="ยังไม่มีกำหนดส่งถัดไป" description="งานที่มีกำหนดส่งในอนาคตจะแสดงที่นี่" />}</section></div><section className="project-section"><div className="section-heading"><div><h2>โปรเจ็คของคุณ</h2><p>ภาพรวมของสิ่งที่คุณกำลังสร้าง</p></div><button className="text-btn" onClick={() => go('projects')}>ดูทั้งหมด <ArrowRight size={15} /></button></div>{active.length ? <div className="project-grid">{active.slice(0, 3).map(p => <ProjectCard key={p.id} project={p} tasks={tasks.filter(t => t.projectId === p.id)} onOpen={() => onOpen(p)} />)}</div> : <Empty title="เริ่มต้นด้วยโปรเจ็คแรก" description="ตั้งเป้าหมาย แบ่งงาน และเลือกเวลาที่จะลงมือทำ" action={<button className="btn primary" onClick={() => go('create')}><Plus size={17} /> สร้างโปรเจ็ค</button>} />}</section></>;
}
function Stat({ label, value, icon, note, warning }: { label: string; value: number; icon: ReactNode; note: string; warning?: boolean }) { return <div className={`stat ${warning ? 'warning' : ''}`}><div><span>{label}</span><span className="stat-icon">{icon}</span></div><strong>{String(value).padStart(2, '0')}</strong><small>{note}</small></div>; }

function TasksPage({ data, onEdit, onStatus, onAdd }: { data: Data; onEdit: (t: Task) => void; onStatus: (t: Task, s: Status) => void; onAdd: () => void }) {
  const [filter, setFilter] = useState('all'); const [search, setSearch] = useState(''); const [projectId, setProjectId] = useState('all'); const active = data.projects.filter(p => !p.archived); const all = data.tasks.filter(t => active.some(p => p.id === t.projectId));
  const filters = [{ id: 'all', name: 'ทั้งหมด', count: all.length }, { id: 'today', name: 'วันนี้', count: all.filter(t => t.status !== 'done' && (datePart(t.start) === today() || datePart(t.due) === today())).length }, { id: 'late', name: 'เลยกำหนด', count: all.filter(overdue).length }, { id: 'doing', name: 'กำลังทำ', count: all.filter(t => t.status === 'doing').length }, { id: 'done', name: 'เสร็จแล้ว', count: all.filter(t => t.status === 'done').length }];
  const shown = all.filter(t => (projectId === 'all' || t.projectId === projectId) && `${t.title} ${active.find(p => p.id === t.projectId)?.name}`.toLowerCase().includes(search.toLowerCase()) && (filter === 'all' || filter === 'today' && t.status !== 'done' && (datePart(t.start) === today() || datePart(t.due) === today()) || filter === 'late' && overdue(t) || filter === t.status)).sort((a, b) => Number(a.status === 'done') - Number(b.status === 'done') || (a.due || '9999').localeCompare(b.due || '9999'));
  return <><div className="page-heading"><div><span className="eyebrow">ONE THING AT A TIME</span><h1>To-do list</h1><p>งานจากทุกโปรเจ็ค เรียงไว้ให้คุณเลือกเริ่มได้ง่ายขึ้น</p></div><button className="btn primary" onClick={onAdd}><Plus size={17} /> เพิ่มงาน</button></div><div className="filter-tabs">{filters.map(f => <button className={filter === f.id ? 'active' : ''} key={f.id} onClick={() => setFilter(f.id)}>{f.name}<span>{f.count}</span></button>)}</div><section className="panel"><div className="list-toolbar"><label className="search-field"><Search size={17} /><input aria-label="ค้นหางาน" placeholder="ค้นหาชื่องานหรือโปรเจ็ค..." value={search} onChange={e => setSearch(e.target.value)} /></label><label className="select-wrap"><Folder size={16} /><select aria-label="กรองโปรเจ็ค" value={projectId} onChange={e => setProjectId(e.target.value)}><option value="all">ทุกโปรเจ็ค</option>{active.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label></div><div className="list-caption"><span>{shown.length} รายการ</span><span>ความสำคัญ <span className="caption-deadline">กำหนดส่ง / สถานะ</span></span></div>{shown.length ? shown.map(t => <TaskRow key={t.id} task={t} project={active.find(p => p.id === t.projectId)} onStatus={onStatus} onEdit={onEdit} />) : <Empty title={all.length ? 'ไม่พบงานที่ตรงกับตัวกรอง' : 'ยังไม่มีงานในรายการ'} description={all.length ? 'ลองเปลี่ยนตัวกรองหรือคำค้นหา' : 'เพิ่มงานแรก แล้วกำหนดเวลาที่เหมาะกับคุณ'} action={!all.length && <button className="btn primary" onClick={onAdd}>เพิ่มงาน</button>} />}</section></>;
}

function CalendarPage({ data, onEdit, onAdd }: { data: Data; onEdit: (t: Task) => void; onAdd: (day?: string) => void }) {
  const [anchor, setAnchor] = useState(today()); const [view, setView] = useState<'month' | 'week'>('month'); const [selected, setSelected] = useState(today()); const [projectId, setProjectId] = useState('all'); const active = data.projects.filter(p => !p.archived); const tasks = data.tasks.filter(t => active.some(p => p.id === t.projectId) && (projectId === 'all' || t.projectId === projectId));
  const weekDay = (date: string) => new Date(`${date}T12:00:00+07:00`).getUTCDay();
  const first = `${anchor.slice(0, 7)}-01`; const gridStart = view === 'month' ? shiftDate(first, -(weekDay(first) + 6) % 7) : shiftDate(anchor, -(weekDay(anchor) + 6) % 7); const dates = Array.from({ length: view === 'month' ? 42 : 7 }, (_, i) => shiftDate(gridStart, i));
  const eventsOn = (day: string) => tasks.flatMap(t => { const events: { task: Task; deadline: boolean }[] = []; if (t.start && datePart(t.start) <= day && datePart(t.end || t.start) >= day) events.push({ task: t, deadline: false }); if (datePart(t.due) === day) events.push({ task: t, deadline: true }); return events; }).sort((a, b) => (a.deadline ? a.task.due : a.task.start).localeCompare(b.deadline ? b.task.due : b.task.start));
  function move(direction: number) { if (view === 'week') setAnchor(shiftDate(anchor, direction * 7)); else { const d = new Date(`${anchor.slice(0, 7)}-01T12:00:00+07:00`); d.setUTCMonth(d.getUTCMonth() + direction); setAnchor(d.toISOString().slice(0, 10)); } }
  const selectedEvents = eventsOn(selected); const selectedTasks = [...new Map(selectedEvents.map(e => [e.task.id, e.task])).values()];
  return <><div className="page-heading"><div><span className="eyebrow">MAKE SPACE IN YOUR DAY</span><h1>ปฏิทิน</h1><p>ช่วงเวลาทำงานและกำหนดส่ง มองเห็นในแผนเดียวกัน</p></div><button className="btn primary" onClick={() => onAdd(selected)}><Plus size={17} /> เพิ่มงาน</button></div><div className="calendar-layout"><section className="panel calendar-panel"><div className="calendar-toolbar"><div className="calendar-title"><h2>{new Intl.DateTimeFormat('th-TH', { month: 'long', year: 'numeric', timeZone: 'Asia/Bangkok' }).format(new Date(`${anchor}T12:00:00+07:00`))}</h2><div><button className="icon-btn" aria-label="ช่วงก่อนหน้า" onClick={() => move(-1)}><ChevronLeft size={18} /></button><button className="icon-btn" aria-label="ช่วงถัดไป" onClick={() => move(1)}><ChevronRight size={18} /></button><button className="btn small outline" onClick={() => { setAnchor(today()); setSelected(today()); }}>วันนี้</button></div></div><div className="segmented"><button className={view === 'month' ? 'active' : ''} onClick={() => setView('month')}>เดือน</button><button className={view === 'week' ? 'active' : ''} onClick={() => setView('week')}>สัปดาห์</button></div></div><div className="calendar-filter"><select aria-label="กรองปฏิทินตามโปรเจ็ค" value={projectId} onChange={e => setProjectId(e.target.value)}><option value="all">ทุกโปรเจ็ค</option>{active.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select><span><i className="legend-block" /> ช่วงทำงาน <i className="legend-deadline" /> กำหนดส่ง</span></div><div className="calendar-scroll"><div className={`calendar-grid ${view}`}><div className="calendar-day-head">จันทร์</div><div className="calendar-day-head">อังคาร</div><div className="calendar-day-head">พุธ</div><div className="calendar-day-head">พฤหัส</div><div className="calendar-day-head">ศุกร์</div><div className="calendar-day-head weekend">เสาร์</div><div className="calendar-day-head weekend">อาทิตย์</div>{dates.map(day => { const events = eventsOn(day); return <div key={day} className={`calendar-cell ${day.slice(0, 7) !== anchor.slice(0, 7) && view === 'month' ? 'outside' : ''} ${day === selected ? 'selected' : ''}`}><button className={`day-number ${day === today() ? 'today' : ''}`} aria-label={`เลือกวันที่ ${day}`} onClick={() => setSelected(day)}>{Number(day.slice(8))}</button><button className="day-add" aria-label={`เพิ่มงานวันที่ ${day}`} onClick={() => onAdd(day)}><Plus size={13} /></button>{events.slice(0, view === 'month' ? 3 : 20).map(e => { const color = active.find(p => p.id === e.task.projectId)?.color || COLORS[0]; return <button key={e.task.id + String(e.deadline)} className={`calendar-event ${e.deadline ? 'deadline' : ''} ${e.task.status === 'done' ? 'finished' : ''}`} style={{ '--event-color': color } as React.CSSProperties} onClick={() => { setSelected(day); onEdit(e.task); }} title={`${e.deadline ? 'กำหนดส่ง' : 'ช่วงทำงาน'}: ${e.task.title}`}><span>{e.deadline ? '◇' : timeLabel(e.task.start)}</span>{e.task.title}</button>; })}{view === 'month' && events.length > 3 && <button className="more-events" onClick={() => setSelected(day)}>+{events.length - 3} รายการ</button>}</div>; })}</div></div><div className="calendar-foot"><span className="tiny-dot" /> เวลาไทย · Asia/Bangkok <span>คลิกวันที่เพื่อดูแผน · กด + เพื่อเพิ่มงาน</span></div></section><aside className="panel day-detail"><div className="section-heading"><div><span className="eyebrow">YOUR DAILY PLAN</span><h2>{dateLabel(selected, true)}</h2><p>{selectedTasks.length} งานในวันนี้</p></div></div>{selectedTasks.length ? selectedTasks.map(t => <button key={t.id} className="day-detail-task" style={{ borderLeftColor: active.find(p => p.id === t.projectId)?.color }} onClick={() => onEdit(t)}><small>{datePart(t.start) === selected ? `${timeLabel(t.start)} – ${timeLabel(t.end)}` : datePart(t.due) === selected ? `ส่ง ${timeLabel(t.due)} น.` : 'งานต่อเนื่อง'}</small><strong>{t.title}</strong><span>{active.find(p => p.id === t.projectId)?.name}</span><Badge kind={t.status}>{STATUS_LABEL[t.status]}</Badge></button>) : <Empty title="ยังไม่มีแผนวันนี้" description="เพิ่มช่วงเวลาทำงานให้สิ่งที่คุณอยากทำ" />}<button className="btn outline full" onClick={() => onAdd(selected)}><Plus size={16} /> เพิ่มงานในวันนี้</button></aside></div></>;
}

type Draft = Task;
function blankTask(projectId = '', day = today()): Draft { return { id: uid(), projectId, title: '', status: 'todo', priority: 'medium', start: '', end: '', due: `${day}T17:00`, reminderBase: 'due', reminderMinutes: -1, remindAt: '', reminded: false }; }
const taskDraft = (task: Task): Draft => ({ ...task, start: inputTime(task.start), end: inputTime(task.end), due: inputTime(task.due) });
function validateTask(t: Draft, project: Pick<Project, 'start' | 'due'>): string {
  if (!t.title.trim()) return 'กรุณากรอกชื่องาน';
  if (!!t.start !== !!t.end) return 'กรุณากำหนดทั้งเวลาเริ่มและสิ้นสุด หรือเว้นว่างทั้งสองช่อง';
  if (t.start && t.end <= t.start) return 'เวลาสิ้นสุดงานต้องอยู่หลังเวลาเริ่ม';
  if (t.start && t.due && t.end > t.due) return 'ช่วงเวลาทำงานต้องไม่เกินกำหนดส่ง';
  for (const v of [t.start, t.end, t.due]) if (v && (v.slice(0, 10) < project.start || v.slice(0, 10) > project.due)) return 'วันของงานต้องอยู่ภายในช่วงวันที่ของโปรเจ็ค';
  const base = t.reminderBase === 'start' ? t.start : t.due;
  if (t.reminderMinutes >= 0 && t.status !== 'done' && !t.reminded) {
    if (!base) return t.reminderBase === 'start' ? 'กรุณากำหนดเวลาเริ่มก่อนตั้งเตือน' : 'กรุณากำหนดเวลาส่งก่อนตั้งเตือน';
    if (new Date(toISO(base)).getTime() - t.reminderMinutes * 60000 <= Date.now()) return 'เวลาแจ้งเตือนต้องอยู่ในอนาคต หรือเลือกไม่แจ้งเตือน';
  }
  return '';
}
function buildTask(draft: Draft): Task { return updateReminder({ ...draft, title: draft.title.trim(), start: toISO(draft.start), end: toISO(draft.end), due: toISO(draft.due) }); }
function TaskFields({ task, onChange, compact = false }: { task: Draft; onChange: (t: Draft) => void; compact?: boolean }) {
  const patch = (key: keyof Task, value: string | number) => onChange({ ...task, [key]: value, ...(['start', 'due', 'reminderBase', 'reminderMinutes', 'status'].includes(key) ? { reminded: false } : {}) });
  return <div className="task-fields"><div className="field-grid"><label className="span-two">ชื่องาน <span className="required">*</span><input aria-label="ชื่องาน" value={task.title} onChange={e => patch('title', e.target.value)} placeholder="เช่น ออกแบบหน้าปฏิทิน" maxLength={160} required={!compact} /></label><label>ความสำคัญ<select value={task.priority} onChange={e => patch('priority', e.target.value)}><option value="low">ต่ำ</option><option value="medium">ปานกลาง</option><option value="high">สูง</option></select></label><label>สถานะ<select value={task.status} onChange={e => patch('status', e.target.value)}><option value="todo">ยังไม่เริ่ม</option><option value="doing">กำลังทำ</option><option value="done">เสร็จแล้ว</option></select></label><label>เริ่มทำงาน <small>ไม่บังคับ</small><input type="datetime-local" value={task.start} onChange={e => patch('start', e.target.value)} /></label><label>สิ้นสุดช่วงทำงาน<input type="datetime-local" value={task.end} onChange={e => patch('end', e.target.value)} /></label><label className="span-two">กำหนดส่ง <small>ไม่บังคับ</small><input aria-label="กำหนดส่ง" type="datetime-local" value={task.due} onChange={e => patch('due', e.target.value)} /></label></div><div className="reminder-fields"><div><Bell size={16} /><strong>แจ้งเตือน</strong></div><label>ช่วงเวลาเตือน<select aria-label="ช่วงเวลาเตือน" value={task.reminderMinutes} onChange={e => patch('reminderMinutes', Number(e.target.value))}><option value={-1}>ไม่แจ้งเตือน</option><option value={0}>เมื่อถึงเวลา</option><option value={10}>ล่วงหน้า 10 นาที</option><option value={30}>ล่วงหน้า 30 นาที</option><option value={60}>ล่วงหน้า 1 ชั่วโมง</option><option value={1440}>ล่วงหน้า 1 วัน</option></select></label>{task.reminderMinutes >= 0 && <label>เตือนก่อน<select aria-label="เตือนก่อน" value={task.reminderBase} onChange={e => patch('reminderBase', e.target.value)}><option value="due">กำหนดส่ง</option><option value="start">เริ่มทำงาน</option></select></label>}</div></div>;
}

function ProjectForm({ original, originalTasks, onSave, onCancel, allTasks }: { original?: Project; originalTasks?: Task[]; onSave: (p: Project, tasks: Task[]) => void; onCancel: () => void; allTasks: Task[] }) {
  const [project, setProject] = useState<Project>(original || { id: uid(), name: '', description: '', color: COLORS[0], start: today(), due: shiftDate(today(), 7), archived: false, createdAt: new Date().toISOString() });
  const [drafts, setDrafts] = useState<Draft[]>(originalTasks?.map(taskDraft) || [blankTask(project.id)]); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const patch = (key: keyof Project, value: string) => setProject({ ...project, [key]: value });
  const populated = drafts.filter(t => t.title.trim());
  const intervals = [...allTasks.filter(t => t.projectId !== project.id && t.status !== 'done'), ...populated.filter(t => t.status !== 'done').map(t => ({ ...t, start: toISO(t.start), end: toISO(t.end) }))].filter(t => t.start && t.end);
  const overlap = intervals.some((a, i) => intervals.slice(i + 1).some(b => a.start < b.end && b.start < a.end && (a.projectId === project.id || b.projectId === project.id)));
  function submit(e: FormEvent) { e.preventDefault(); setError(''); if (!project.name.trim()) { setError('กรุณากรอกชื่อโปรเจ็ค'); return; } if (!project.start || !project.due || project.start > project.due) { setError('วันเริ่มโปรเจ็คต้องไม่อยู่หลังกำหนดส่ง'); return; } for (let i = 0; i < populated.length; i++) { const message = validateTask(populated[i], project); if (message) { setError(`งานที่ ${i + 1}: ${message}`); return; } } try { setBusy(true); onSave({ ...project, name: project.name.trim(), description: project.description.trim() }, populated.map(t => { const built = buildTask({ ...t, projectId: project.id }); const old = originalTasks?.find(o => o.id === t.id); return old && old.start === built.start && old.due === built.due && old.reminderBase === built.reminderBase && old.reminderMinutes === built.reminderMinutes && old.status === built.status ? { ...built, remindAt: old.remindAt, reminded: old.reminded } : built; })); } catch (e) { setError(e instanceof Error ? e.message : 'บันทึกไม่ได้'); setBusy(false); } }
  return <><button className="back-link" onClick={onCancel}><ArrowLeft size={16} /> กลับไปที่โปรเจ็ค</button><div className="page-heading"><div><span className="eyebrow">TURN YOUR IDEA INTO A PLAN</span><h1>{original ? 'แก้ไขโปรเจ็ค' : 'สร้างโปรเจ็คใหม่'}</h1><p>ตั้งเป้าหมาย แบ่งเป็นงานเล็ก ๆ แล้วเลือกเวลาที่จะเริ่ม</p></div></div><form className="project-form-layout" onSubmit={submit}><div><section className="panel form-section"><div className="section-number">01</div><div className="section-heading"><div><h2>เริ่มจากโปรเจ็คของคุณ</h2><p>ให้ทุกแผนมีชื่อและกำหนดส่งที่ชัดเจน</p></div><FolderOpen size={21} /></div><label>ชื่อโปรเจ็ค <span className="required">*</span><input value={project.name} onChange={e => patch('name', e.target.value)} placeholder="เช่น โปรเจ็คจบวิชา Software Engineering" maxLength={120} required /></label><label>รายละเอียด<textarea value={project.description} onChange={e => patch('description', e.target.value)} placeholder="โปรเจ็คนี้เกี่ยวกับอะไร และอยากทำอะไรให้สำเร็จ?" rows={3} maxLength={1000} /></label><div className="field-grid"><label>วันที่เริ่ม <span className="required">*</span><input type="date" value={project.start} onChange={e => patch('start', e.target.value)} required /></label><label>กำหนดส่งโปรเจ็ค <span className="required">*</span><input type="date" value={project.due} onChange={e => patch('due', e.target.value)} required /></label></div><label>สีของโปรเจ็ค</label><div className="color-options">{COLORS.map((color, i) => <button key={color} type="button" style={{ background: color }} aria-label={`สีโปรเจ็ค ${i + 1}`} aria-pressed={project.color === color} onClick={() => patch('color', color)}>{project.color === color && <Check size={19} />}</button>)}</div></section><section className="panel form-section"><div className="section-number">02</div><div className="section-heading"><div><h2>แบ่งเป็นงานที่ลงมือทำได้</h2><p>กำหนดช่วงทำงานและกำหนดส่งแยกกัน · เวลาไทย</p></div><ListTodo size={21} /></div>{drafts.map((task, index) => <div className="task-draft" key={task.id}><div className="task-draft-header"><span>งานที่ {index + 1}</span><button className="icon-btn danger" type="button" aria-label={`ลบงานที่ ${index + 1}`} onClick={() => setDrafts(drafts.filter(t => t.id !== task.id))}><Trash2 size={16} /></button></div><TaskFields task={task} compact onChange={updated => setDrafts(drafts.map(t => t.id === updated.id ? updated : t))} /></div>)}<button className="add-task-btn" type="button" onClick={() => setDrafts([...drafts, blankTask(project.id, project.start)])}><Plus size={17} /> เพิ่มงานย่อย</button></section></div><aside className="form-summary panel"><span className="eyebrow">YOUR PLAN, READY TO GO</span><h2>สรุปก่อนบันทึก</h2><div className="summary-project"><span className="folder-tile" style={{ color: project.color, background: `${project.color}18` }}><Folder size={22} /></span><strong>{project.name || 'โปรเจ็คใหม่ของคุณ'}</strong></div><div className="summary-row"><span>เริ่ม</span><strong>{dateLabel(project.start)}</strong></div><div className="summary-row"><span>กำหนดส่ง</span><strong>{dateLabel(project.due)}</strong></div><div className="summary-row"><span>งานย่อย</span><strong>{populated.length} งาน</strong></div><div className="summary-row"><span>ตั้งแจ้งเตือน</span><strong>{populated.filter(t => t.reminderMinutes >= 0 && t.status !== 'done').length} งาน</strong></div><div className="summary-note"><CalendarDays size={18} /><p>งานที่บันทึกจะแสดงใน To-do list ปฏิทิน และภาพรวมทันที</p></div>{overlap && <div className="form-warning"><AlertTriangle size={17} /> มีช่วงเวลาทำงานซ้อนกัน คุณยังบันทึกได้ หรือปรับเวลาก่อนเริ่ม</div>}{error && <div className="form-error" role="alert">{error}</div>}<button className="btn primary full" disabled={busy}><Check size={17} /> {original ? 'บันทึกการแก้ไข' : 'สร้างโปรเจ็ค'}</button><button className="btn ghost full" type="button" onClick={onCancel}>ยกเลิก</button><small>งานที่ไม่กรอกชื่อจะไม่ถูกบันทึก<br />สร้างโปรเจ็คเปล่าแล้วเพิ่มงานภายหลังได้</small></aside></form></>;
}

function TaskEditor({ task, projects, tasks, onSave, onClose, onDelete, onSimulate, onSnooze }: { task: Task; projects: Project[]; tasks: Task[]; onSave: (t: Task) => void; onClose: () => void; onDelete?: () => void; onSimulate?: () => void; onSnooze?: () => void }) {
  const [draft, setDraft] = useState(taskDraft(task)); const [error, setError] = useState(''); const selectedProject = projects.find(p => p.id === draft.projectId); const overlap = draft.start && draft.end && tasks.some(t => t.id !== draft.id && t.status !== 'done' && t.start && t.end && t.start < toISO(draft.end) && toISO(draft.start) < t.end);
  function submit(e: FormEvent) { e.preventDefault(); if (!selectedProject) { setError('กรุณาเลือกโปรเจ็ค'); return; } const message = validateTask(draft, selectedProject); if (message) { setError(message); return; } const built = buildTask(draft); const unchanged = built.start === task.start && built.due === task.due && built.reminderBase === task.reminderBase && built.reminderMinutes === task.reminderMinutes && built.status === task.status; try { onSave(unchanged ? { ...built, remindAt: task.remindAt, reminded: task.reminded } : built); } catch (e) { setError(e instanceof Error ? e.message : 'บันทึกไม่ได้'); } }
  return <Modal title={onDelete ? 'รายละเอียดและแก้ไขงาน' : 'เพิ่มงานใหม่'} onClose={onClose} wide><form onSubmit={submit} className="modal-body"><label>โปรเจ็ค <span className="required">*</span><select value={draft.projectId} onChange={e => setDraft({ ...draft, projectId: e.target.value })} required><option value="" disabled>เลือกโปรเจ็ค</option>{projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label><TaskFields task={draft} onChange={setDraft} />{overlap && <div className="form-warning"><AlertTriangle size={16} /> ช่วงเวลานี้ซ้อนกับงานอื่น คุณยังสามารถบันทึกได้</div>}{task.remindAt && task.status !== 'done' && <p className="reminder-info"><Bell size={14} /> {task.reminded ? 'ส่งแจ้งเตือนแล้ว' : `เตือนครั้งถัดไป ${dateLabel(task.remindAt)} ${timeLabel(task.remindAt)} น.`}</p>}{onSimulate && task.status !== 'done' && <div className="demo-task-actions"><button className="btn outline small" type="button" onClick={onSimulate}><BellRing size={15} /> จำลองถึงเวลาแจ้งเตือน</button>{onSnooze && <button className="btn outline small" type="button" onClick={onSnooze}><Clock3 size={15} /> เตือนอีก 10 นาที</button>}</div>}{error && <div className="form-error" role="alert">{error}</div>}<div className="modal-actions">{onDelete && <button className="btn danger-text" type="button" onClick={onDelete}><Trash2 size={16} /> ลบงาน</button>}<div><button className="btn ghost" type="button" onClick={onClose}>ยกเลิก</button><button className="btn primary" type="submit"><Check size={16} /> บันทึกงาน</button></div></div></form></Modal>;
}

export default function App() {
  const [user, setUser] = useState<DemoUser | null>(readUser); const [auth, setAuth] = useState<'login' | 'register' | null>(null); const [page, setPage] = useState<Page>(route); const [data, setData] = useState<Data>(() => { const u = readUser(); if (!u) return emptyData(); try { return loadData(u); } catch { return emptyData(); } }); const dataRef = useRef(data);
  const [selectedId, setSelectedId] = useState(() => { try { return sessionStorage.getItem('projectrecord.demo.selected') || ''; } catch { return ''; } }); const [editProject, setEditProject] = useState<Project | undefined>(); const [editingTask, setEditingTask] = useState<Task | null>(null); const [toast, setToast] = useState(''); const [mobileNav, setMobileNav] = useState(false); const [confirm, setConfirm] = useState<{ title: string; description: string; action: () => void } | null>(null); const [projectFilter, setProjectFilter] = useState('active'); const [projectSearch, setProjectSearch] = useState(''); const [storageError, setStorageError] = useState('');
  const selectedProject = data.projects.find(p => p.id === selectedId); const activeProjects = data.projects.filter(p => !p.archived); const unread = data.notices.filter(n => !n.read).length;
  function notify(message: string) { setToast(message); }
  function commit(next: Data) { if (!user) return; try { localStorage.setItem(DATA_PREFIX + user.id, JSON.stringify(next)); dataRef.current = next; setData(next); setStorageError(''); } catch { setStorageError('บันทึกข้อมูลไม่ได้ พื้นที่จัดเก็บอาจเต็มหรือถูกปิดใช้งาน'); throw new Error('บันทึกข้อมูลไม่ได้ กรุณาตรวจพื้นที่จัดเก็บของเบราว์เซอร์'); } }
  function go(next: Page) { setPage(next); location.hash = next; setMobileNav(false); window.scrollTo({ top: 0, behavior: 'instant' }); }
  function openProject(project: Project) { setSelectedId(project.id); try { sessionStorage.setItem('projectrecord.demo.selected', project.id); } catch { /* Selection still works in memory. */ } setEditProject(undefined); go('detail'); }
  function startUser(nextUser: DemoUser) { const next = loadData(nextUser); localStorage.setItem(SESSION, JSON.stringify(nextUser)); localStorage.setItem(DATA_PREFIX + nextUser.id, JSON.stringify(next)); dataRef.current = next; setData(next); setUser(nextUser); setAuth(null); setSelectedId(''); setEditProject(undefined); setEditingTask(null); go('dashboard'); }
  function demoLogin() { try { startUser(DEMO_USER); } catch (e) { notify(e instanceof Error ? e.message : 'เปิดเดโมไม่ได้'); } }
  function safeAction(action: () => void) { try { action(); } catch (e) { notify(e instanceof Error ? e.message : 'ดำเนินการไม่สำเร็จ'); } }
  function changeStatus(task: Task, status: Status) { safeAction(() => { const updated = status === 'done' ? { ...task, status, remindAt: '', reminded: true } : updateReminder({ ...task, status }); if (updated.remindAt && new Date(updated.remindAt).getTime() <= Date.now()) updated.reminded = true; commit({ ...dataRef.current, tasks: dataRef.current.tasks.map(t => t.id === task.id ? updated : t) }); notify(status === 'done' ? 'อีกหนึ่งงานสำเร็จแล้ว เก่งมาก!' : 'อัปเดตสถานะงานแล้ว'); }); }
  function addTask(day?: string) { if (!activeProjects.length) { notify('สร้างโปรเจ็คก่อน แล้วเพิ่มงานย่อยได้เลย'); setEditProject(undefined); go('create'); return; } const p = page === 'detail' && selectedProject && !selectedProject.archived ? selectedProject : activeProjects[0]; const draft = blankTask(p.id, day || today()); setEditingTask({ ...draft, due: toISO(draft.due) }); }
  function saveTask(task: Task) { const exists = data.tasks.some(t => t.id === task.id); commit({ ...dataRef.current, tasks: exists ? dataRef.current.tasks.map(t => t.id === task.id ? task : t) : [...dataRef.current.tasks, task] }); setEditingTask(null); notify(exists ? 'บันทึกการแก้ไขแล้ว ทุกหน้าอัปเดตตามกัน' : 'เพิ่มงานแล้ว ดูได้ในปฏิทินและ To-do list'); }
  function simulate(task: Task) { if (task.status === 'done') return; safeAction(() => { const notice = makeNotice(task, true); commit({ ...dataRef.current, notices: [notice, ...dataRef.current.notices] }); setEditingTask(null); notify(`จำลองแจ้งเตือน: ${task.title}`); }); }
  function snooze(task: Task) { safeAction(() => { const updated = { ...task, remindAt: new Date(Date.now() + 10 * 60000).toISOString(), reminded: false }; commit({ ...dataRef.current, tasks: dataRef.current.tasks.map(t => t.id === task.id ? updated : t) }); setEditingTask(null); notify('ตั้งเตือนอีกครั้งใน 10 นาทีแล้ว'); }); }
  function browserPermission() { if (!('Notification' in window)) { notify('เบราว์เซอร์นี้ไม่รองรับการแจ้งเตือน ใช้กระดิ่งในแอปได้'); return; } Notification.requestPermission().then(permission => notify(permission === 'granted' ? 'เปิดแจ้งเตือนเบราว์เซอร์แล้ว ทดสอบได้ขณะเปิดเว็บ' : 'ยังใช้การแจ้งเตือนในแอปได้ตามปกติ')).catch(() => notify('เปิดการแจ้งเตือนไม่ได้ แต่กระดิ่งในแอปยังใช้งานได้')); }
  useEffect(() => { const fn = () => setPage(route()); window.addEventListener('hashchange', fn); return () => window.removeEventListener('hashchange', fn); }, []);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 5500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => {
    if (!user) return;
    function checkDue() {
      const current = dataRef.current; const due = current.tasks.filter(t => t.remindAt && !t.reminded && t.status !== 'done' && new Date(t.remindAt).getTime() <= Date.now() && current.projects.some(p => p.id === t.projectId && !p.archived)); if (!due.length) return;
      safeAction(() => { const notices = due.map(t => makeNotice(t)); commit({ ...current, tasks: current.tasks.map(t => due.some(d => d.id === t.id) ? { ...t, reminded: true } : t), notices: [...notices, ...current.notices] }); notify(`ถึงเวลาแจ้งเตือน ${due.length} งาน · ดูรายละเอียดที่กระดิ่ง`); if ('Notification' in window && Notification.permission === 'granted') notices.forEach(n => { try { const browserNotice = new Notification(n.title, { body: n.message, tag: n.id }); browserNotice.onclick = () => { window.focus(); setEditingTask(dataRef.current.tasks.find(t => t.id === n.taskId) || null); browserNotice.close(); }; } catch { /* In-app notices are always retained, including on mobile. */ } }); });
    }
    checkDue(); const timer = setInterval(checkDue, 10000); const onVisibility = () => { if (document.visibilityState === 'visible') checkDue(); }; document.addEventListener('visibilitychange', onVisibility);
    const onStorage = (e: StorageEvent) => { if (e.key === DATA_PREFIX + user.id) { try { const latest = loadData(user); dataRef.current = latest; setData(latest); } catch { setStorageError('อ่านข้อมูลจากแท็บอื่นไม่ได้'); } } if (e.key === SESSION && e.newValue !== JSON.stringify(user)) { setUser(null); setAuth(null); setEditingTask(null); setConfirm(null); } };
    window.addEventListener('storage', onStorage); return () => { clearInterval(timer); document.removeEventListener('visibilitychange', onVisibility); window.removeEventListener('storage', onStorage); };
  }, [user]);
  const toastView = toast && <div className="toast" role="status"><CheckCheck size={18} /><span>{toast}</span><button className="icon-btn" aria-label="ปิดข้อความ" onClick={() => setToast('')}><X size={16} /></button></div>;
  if (!user) return <>{auth ? <Auth type={auth} onType={setAuth} onBack={() => { setAuth(null); location.hash = ''; }} onUser={startUser} onDemo={demoLogin} /> : <Landing onAuth={setAuth} onDemo={demoLogin} />}{toastView}</>;
  const visibleProjects = data.projects.filter(p => (projectFilter === 'archived' ? p.archived : !p.archived) && `${p.name} ${p.description}`.toLowerCase().includes(projectSearch.toLowerCase()));
  return <div className="workspace"><aside className={`sidebar ${mobileNav ? 'open' : ''}`}><div className="sidebar-brand"><Brand /><button className="icon-btn mobile-only" aria-label="ปิดเมนู" onClick={() => setMobileNav(false)}><X size={20} /></button></div><div className="workspace-label"><span className="workspace-avatar">P</span><div><strong>พื้นที่ทำงานส่วนตัว</strong><small>Personal workspace</small></div></div><span className="nav-label">WORKSPACE</span><nav className="side-nav">{NAV.map(item => <button key={item.id} aria-label={item.label} className={page === item.id || item.id === 'projects' && ['create', 'detail'].includes(page) ? 'active' : ''} onClick={() => { setEditProject(undefined); go(item.id); }}><item.icon size={19} /><span>{item.label}</span>{item.id === 'projects' && <small>{activeProjects.length}</small>}</button>)}</nav><div className="side-projects"><div className="nav-label">YOUR PROJECTS<button className="icon-btn" aria-label="สร้างโปรเจ็คจากเมนู" onClick={() => { setEditProject(undefined); go('create'); }}><Plus size={15} /></button></div>{activeProjects.slice(0, 4).map(p => <button key={p.id} onClick={() => openProject(p)}><span style={{ background: p.color }} />{p.name}</button>)}{!activeProjects.length && <small>โปรเจ็คแรกของคุณจะอยู่ที่นี่</small>}</div><div className="sidebar-bottom"><div className="sidebar-tip"><span><Sparkles size={17} /> ONE SMALL STEP</span><p>แบ่งงานให้เล็กลง<br />แล้วแผนใหญ่จะเริ่มง่ายขึ้น</p></div><button className="notification-nav" onClick={() => go('notifications')}><Bell size={18} /> การแจ้งเตือน{unread > 0 && <span>{unread}</span>}</button><div className="user-card"><span className="user-avatar">{user.name.slice(0, 1)}</span><div><strong>{user.name}</strong><small>บัญชีจำลอง</small></div><button className="icon-btn" title="ออกจากระบบ" aria-label="ออกจากระบบ" onClick={() => safeAction(() => { localStorage.removeItem(SESSION); setUser(null); setAuth(null); setEditingTask(null); setConfirm(null); location.hash = ''; })}><LogOut size={17} /></button></div></div></aside>{mobileNav && <button className="sidebar-scrim" aria-label="ปิดเมนูด้านข้าง" onClick={() => setMobileNav(false)} />}
  <div className="workspace-main"><header className="topbar"><div><button className="icon-btn mobile-only" aria-label="เปิดเมนู" onClick={() => setMobileNav(true)}><Menu size={21} /></button><span>พื้นที่ทำงาน</span><ChevronRight size={13} /><strong>{PAGE_NAMES[page]}</strong></div><div><span className="topbar-date"><CalendarDays size={15} /> {dateLabel(today(), true)}</span><span className="demo-tag"><span /> DEMO</span><button className="icon-btn bell-button" aria-label={`การแจ้งเตือน ${unread} รายการยังไม่อ่าน`} onClick={() => go('notifications')}><Bell size={20} />{unread > 0 && <span>{unread}</span>}</button></div></header><main className="content">{storageError && <div className="form-error" role="alert">{storageError}</div>}
    {page === 'dashboard' && <Dashboard data={data} user={user} go={p => { setEditProject(undefined); go(p); }} onOpen={openProject} onEdit={setEditingTask} onStatus={changeStatus} />}
    {page === 'tasks' && <TasksPage data={data} onEdit={setEditingTask} onStatus={changeStatus} onAdd={() => addTask()} />}
    {page === 'calendar' && <CalendarPage data={data} onEdit={setEditingTask} onAdd={addTask} />}
    {page === 'create' && <ProjectForm key={editProject?.id || 'new'} original={editProject} originalTasks={editProject ? data.tasks.filter(t => t.projectId === editProject.id) : undefined} allTasks={data.tasks.filter(t => activeProjects.some(p => p.id === t.projectId))} onCancel={() => editProject ? go('detail') : go('projects')} onSave={(p, tasks) => { const exists = data.projects.some(project => project.id === p.id); const removedIds = data.tasks.filter(t => t.projectId === p.id && !tasks.some(next => next.id === t.id)).map(t => t.id); commit({ projects: exists ? data.projects.map(project => project.id === p.id ? p : project) : [...data.projects, p], tasks: [...data.tasks.filter(t => t.projectId !== p.id), ...tasks], notices: data.notices.filter(n => !removedIds.includes(n.taskId)) }); setEditProject(undefined); openProject(p); notify(exists ? 'อัปเดตโปรเจ็คแล้ว' : 'สร้างโปรเจ็คแล้ว พร้อมเริ่มแผนของคุณ'); }} />}
    {page === 'projects' && <><div className="page-heading"><div><span className="eyebrow">A HOME FOR EVERY IDEA</span><h1>โปรเจ็คของฉัน</h1><p>ทุกเป้าหมายของคุณ พร้อมพื้นที่ให้เดินหน้าต่อ</p></div><button className="btn primary" onClick={() => { setEditProject(undefined); go('create'); }}><Plus size={17} /> สร้างโปรเจ็ค</button></div><div className="projects-toolbar"><div className="filter-tabs"><button className={projectFilter === 'active' ? 'active' : ''} onClick={() => setProjectFilter('active')}>กำลังดำเนินการ <span>{activeProjects.length}</span></button><button className={projectFilter === 'archived' ? 'active' : ''} onClick={() => setProjectFilter('archived')}>เก็บเข้าคลัง <span>{data.projects.filter(p => p.archived).length}</span></button></div><label className="search-field"><Search size={17} /><input aria-label="ค้นหาโปรเจ็ค" placeholder="ค้นหาโปรเจ็ค..." value={projectSearch} onChange={e => setProjectSearch(e.target.value)} /></label></div>{visibleProjects.length ? <div className="project-grid">{visibleProjects.map(p => <ProjectCard key={p.id} project={p} tasks={data.tasks.filter(t => t.projectId === p.id)} onOpen={() => openProject(p)} />)}</div> : <Empty title={projectSearch ? 'ไม่พบโปรเจ็คที่ค้นหา' : projectFilter === 'archived' ? 'ยังไม่มีโปรเจ็คในคลัง' : 'พื้นที่ว่างสำหรับไอเดียใหม่'} description="สร้างโปรเจ็ค แล้วแบ่งเป็นงานที่เริ่มทำได้" action={projectFilter === 'active' && <button className="btn primary" onClick={() => go('create')}><Plus size={17} /> สร้างโปรเจ็ค</button>} />}</>}
    {page === 'detail' && (selectedProject ? <><button className="back-link" onClick={() => go('projects')}><ArrowLeft size={16} /> โปรเจ็คทั้งหมด</button><div className="page-heading"><div><span className="eyebrow">YOUR PROJECT, YOUR PROGRESS</span><h1><span className="project-color-dot" style={{ background: selectedProject.color }} />{selectedProject.name}</h1><p>{selectedProject.description || 'ยังไม่มีรายละเอียดโปรเจ็ค'}</p></div><div className="heading-actions"><button className="btn outline" onClick={() => { setEditProject(selectedProject); go('create'); }}><Pencil size={16} /> แก้ไขโปรเจ็ค</button><button className="icon-btn" aria-label={selectedProject.archived ? 'นำโปรเจ็คกลับมา' : 'เก็บโปรเจ็คเข้าคลัง'} title={selectedProject.archived ? 'นำกลับมา' : 'เก็บเข้าคลัง'} onClick={() => setConfirm({ title: selectedProject.archived ? 'นำโปรเจ็คกลับมา?' : 'เก็บโปรเจ็คเข้าคลัง?', description: selectedProject.archived ? 'โปรเจ็คจะกลับมาแสดงในภาพรวมและปฏิทิน การเตือนที่ค้างไว้จะเริ่มตรวจอีกครั้ง' : 'ข้อมูลยังอยู่ แต่โปรเจ็คและงานจะถูกซ่อนจากภาพรวม ปฏิทิน และหยุดแจ้งเตือนจนกว่าจะนำกลับมา', action: () => { commit({ ...data, projects: data.projects.map(p => p.id === selectedProject.id ? { ...p, archived: !p.archived } : p) }); notify(selectedProject.archived ? 'นำโปรเจ็คกลับมาแล้ว' : 'เก็บโปรเจ็คเข้าคลังแล้ว'); } })}><Archive size={19} /></button><button className="icon-btn danger" aria-label="ลบโปรเจ็ค" onClick={() => setConfirm({ title: 'ลบโปรเจ็คนี้?', description: 'โปรเจ็ค งานย่อย และประวัติแจ้งเตือนของโปรเจ็คนี้จะถูกลบจากเบราว์เซอร์', action: () => { const ids = data.tasks.filter(t => t.projectId === selectedProject.id).map(t => t.id); commit({ projects: data.projects.filter(p => p.id !== selectedProject.id), tasks: data.tasks.filter(t => t.projectId !== selectedProject.id), notices: data.notices.filter(n => !ids.includes(n.taskId)) }); go('projects'); notify('ลบโปรเจ็คแล้ว'); } })}><Trash2 size={19} /></button></div></div>{selectedProject.archived && <div className="form-warning"><Archive size={17} /> โปรเจ็คอยู่ในคลัง การแจ้งเตือนถูกพักไว้</div>}<div className="detail-overview panel"><div><span>ช่วงโปรเจ็ค</span><strong>{dateLabel(selectedProject.start)} – {dateLabel(selectedProject.due, true)}</strong></div><div><span>งานทั้งหมด</span><strong>{data.tasks.filter(t => t.projectId === selectedProject.id).length} งาน</strong></div><div className="detail-progress"><div><span>ความคืบหน้า</span><strong>{progress(data.tasks.filter(t => t.projectId === selectedProject.id))}%</strong></div><div className="progress-track"><span style={{ width: `${progress(data.tasks.filter(t => t.projectId === selectedProject.id))}%`, background: selectedProject.color }} /></div></div></div><section className="panel"><div className="section-heading"><div><h2>งานในโปรเจ็ค</h2><p>ปรับแผนหรือทำเครื่องหมายเมื่อสำเร็จ</p></div>{!selectedProject.archived && <button className="btn outline small" onClick={() => addTask()}><Plus size={16} /> เพิ่มงาน</button>}</div>{data.tasks.some(t => t.projectId === selectedProject.id) ? data.tasks.filter(t => t.projectId === selectedProject.id).map(t => <TaskRow key={t.id} task={t} project={selectedProject} onStatus={changeStatus} onEdit={setEditingTask} />) : <Empty title="แบ่งเป้าหมายเป็นงานแรก" description="เพิ่มงานย่อยเพื่อเริ่มวางแผนและติดตามความคืบหน้า" />}</section></> : <Empty title="เลือกโปรเจ็คที่ต้องการดู" description="เปิดโปรเจ็คจากรายการของคุณ" action={<button className="btn primary" onClick={() => go('projects')}>ดูโปรเจ็คทั้งหมด</button>} />)}
    {page === 'notifications' && <><div className="page-heading"><div><span className="eyebrow">A GENTLE NUDGE, RIGHT ON TIME</span><h1>การแจ้งเตือน</h1><p>สิ่งที่ควรจำ พร้อมทางลัดกลับไปที่งาน</p></div><button className="btn outline" onClick={browserPermission}><BellRing size={17} /> เปิดเตือนเบราว์เซอร์</button></div><div className="notification-info"><Bell size={20} /><div><strong>แจ้งเตือนขณะเปิดเว็บเดโม</strong><p>เมื่อกลับเข้าเว็บ ระบบจะตรวจรายการเตือนที่เลยเวลามาแล้ว การเตือนเมื่อปิดแท็บต้องเชื่อมระบบเซิร์ฟเวอร์เพิ่มเติม</p></div></div><section className="panel"><div className="section-heading"><div><h2>รายการแจ้งเตือน <span className="count-chip">{unread}</span></h2><p>{unread} รายการยังไม่อ่าน</p></div><div className="heading-actions"><button className="text-btn" onClick={() => safeAction(() => { commit({ ...data, notices: data.notices.map(n => ({ ...n, read: true })) }); notify('อ่านการแจ้งเตือนทั้งหมดแล้ว'); })}><CheckCheck size={16} /> อ่านทั้งหมด</button><button className="btn outline small" disabled={!data.tasks.some(t => t.status !== 'done' && activeProjects.some(p => p.id === t.projectId))} onClick={() => { const task = data.tasks.find(t => t.status !== 'done' && activeProjects.some(p => p.id === t.projectId)); if (task) simulate(task); }}><Play size={14} /> จำลองแจ้งเตือน</button></div></div>{data.notices.length ? data.notices.map(n => <div className={`notice-row ${n.read ? '' : 'unread'}`} key={n.id}><span className="notice-icon"><Bell size={18} /></span><button className="notice-copy" onClick={() => safeAction(() => { commit({ ...data, notices: data.notices.map(x => x.id === n.id ? { ...x, read: true } : x) }); const task = data.tasks.find(t => t.id === n.taskId); if (task) setEditingTask(task); else notify('งานนี้ถูกลบแล้ว'); })}><strong>{n.title}{n.simulated && <Badge kind="neutral">จำลองเวลา</Badge>}</strong><p>{n.message}</p><small>{dateLabel(n.createdAt)} · {timeLabel(n.createdAt)} น.</small></button><button className="icon-btn" aria-label={`ลบการแจ้งเตือน ${n.title}`} onClick={() => safeAction(() => commit({ ...data, notices: data.notices.filter(x => x.id !== n.id) }))}><X size={17} /></button></div>) : <Empty title="ยังไม่มีการแจ้งเตือน" description="ตั้งเวลาเตือนในงาน หรือกดจำลองเพื่อดูตัวอย่าง" />}</section><section className="panel reminder-queue"><div className="section-heading"><div><h2>รายการรอแจ้งเตือน</h2><p>เลื่อนเวลาได้จากรายละเอียดงาน</p></div><Clock3 size={20} /></div>{data.tasks.filter(t => t.remindAt && !t.reminded && t.status !== 'done' && activeProjects.some(p => p.id === t.projectId)).sort((a, b) => a.remindAt.localeCompare(b.remindAt)).map(t => <button className="queued-reminder" key={t.id} onClick={() => setEditingTask(t)}><span>{t.title}</span><strong>{dateLabel(t.remindAt)} {timeLabel(t.remindAt)} น.</strong><ChevronRight size={16} /></button>)}{!data.tasks.some(t => t.remindAt && !t.reminded && t.status !== 'done' && activeProjects.some(p => p.id === t.projectId)) && <p className="muted">ยังไม่มีงานที่ตั้งเวลาเตือนไว้</p>}</section></>}
    <footer className="workspace-footer"><span><Leaf size={13} /> ทีละงาน ทีละก้าว</span><div><span>ข้อมูลเก็บในเบราว์เซอร์นี้ · เวลาไทย</span>{user.id === DEMO_USER.id && <button className="text-btn" onClick={() => setConfirm({ title: 'เริ่มเดโมใหม่ด้วยข้อมูลตัวอย่าง?', description: 'โปรเจ็คและงานที่เพิ่มในบัญชีเดโมจะถูกแทนที่ด้วยตัวอย่าง บัญชีจำลองอื่นจะไม่เปลี่ยน', action: () => { commit(seedData()); setEditingTask(null); setEditProject(undefined); go('dashboard'); notify('เตรียมข้อมูลตัวอย่างสำหรับเดโมใหม่แล้ว'); } })}><RotateCcw size={13} /> เริ่มเดโมใหม่</button>}</div></footer>
  </main></div>{editingTask && <TaskEditor key={editingTask.id} task={data.tasks.find(t => t.id === editingTask.id) || editingTask} projects={data.projects.filter(p => !p.archived || p.id === editingTask.projectId)} tasks={data.tasks.filter(t => activeProjects.some(p => p.id === t.projectId))} onSave={saveTask} onClose={() => setEditingTask(null)} onDelete={data.tasks.some(t => t.id === editingTask.id) ? () => setConfirm({ title: 'ลบงานนี้?', description: 'งานจะถูกลบจากทุกหน้า และรายการเตือนของงานนี้จะถูกยกเลิก', action: () => { commit({ ...data, tasks: data.tasks.filter(t => t.id !== editingTask.id), notices: data.notices.filter(n => n.taskId !== editingTask.id) }); setEditingTask(null); notify('ลบงานและยกเลิกการเตือนแล้ว'); } }) : undefined} onSimulate={data.tasks.some(t => t.id === editingTask.id) && !data.projects.find(p => p.id === editingTask.projectId)?.archived ? () => simulate(data.tasks.find(t => t.id === editingTask.id)!) : undefined} onSnooze={data.tasks.some(t => t.id === editingTask.id) && !data.projects.find(p => p.id === editingTask.projectId)?.archived ? () => snooze(data.tasks.find(t => t.id === editingTask.id)!) : undefined} />}{confirm && <Modal title={confirm.title} onClose={() => setConfirm(null)}><div className="modal-body"><p>{confirm.description}</p><div className="modal-actions"><span /><div><button className="btn ghost" onClick={() => setConfirm(null)}>ยกเลิก</button><button className="btn primary" onClick={() => safeAction(() => { confirm.action(); setConfirm(null); })}>ยืนยัน</button></div></div></div></Modal>}{toastView}</div>;
}
